'use strict';
const fs = require('fs');

function main() {
  const path = process.argv[2];
  if (!path) { console.error('usage: node extract.js <elf>'); process.exit(2); }
  const buf = fs.readFileSync(path);

  // ELF magic
  if (buf.length < 64 || buf.readUInt32LE(0) !== 0x464c457f) {
    console.error('not an ELF file'); process.exit(1);
  }
  const is64 = buf[4] === 2;
