    const segEnd = BASE + p_vaddr + p_memsz;
    const fileEnd = p_offset + p_filesz;

    // align start up to 4-byte boundary
    let addr = Math.ceil(segStart / 4) * 4;
    for (; addr + 4 <= segEnd; addr += 4) {
      const rel = addr - (BASE + p_vaddr);
      const fo = p_offset + rel;
      // read 4 bytes little-endian, zero-pad bytes beyond the file-backed region (bss gap)
      let v = 0;
      for (let k = 0; k < 4; k++) {
        const b = (fo + k >= 0 && fo + k < fileEnd && fo + k < buf.length) ? buf[fo + k] : 0;
        v |= b << (8 * k);
      }
      out[addr] = v >>> 0;
    }
  }

  process.stdout.write(JSON.stringify(out) + '\n');
